with unpacked as (select id, plan, currency, tier_limits, tier_prices, element_at(tier_prices, 1) as entry_price, array_min(tier_prices) as lowest_price from price_tiers) select case when lowest_price >= 36 then 'HIGH' else 'LOW' end as lowest_price_tier, size(collect_set(currency)) as num_currencies, sum(case when plan = 'enterprise' then lowest_price else 0 end) as enterprise_lowest_price from unpacked group by case when lowest_price >= 36 then 'HIGH' else 'LOW' end
